/**
 * Post-build prerender script — renders SPA pages to static HTML.
 * Runs after `vite build`.
 *
 * Reads routes from public/routes.json (generated by generate-sitemap.cjs),
 * uses Puppeteer to render each page, saves HTML to dist/__prerendered__/.
 *
 * Usage: node scripts/prerender.mjs
 *   --serve-dir  Path to dist directory (default: dist)
 *   --routes     Path to routes JSON (default: public/routes.json)
 *   --concurrency Number of parallel pages (default: 3)
 *   --timeout    Page load timeout ms (default: 15000)
 *   --strict     Fail build if any page fails to render
 */

import { createServer } from "http";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "fs";
import path from "path";
import { fileURLToPath } from "url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..");
const PUBLIC = path.resolve(ROOT, "public");

function readArgument(name, fallback) {
  const index = process.argv.indexOf(name);
  return index >= 0 && process.argv[index + 1] ? process.argv[index + 1] : fallback;
}

const DIST = path.resolve(ROOT, readArgument("--serve-dir", "dist"));
const ROUTES_FILE = path.resolve(ROOT, readArgument("--routes", "public/routes.json"));
const OUTPUT_DIR = path.resolve(DIST, "__prerendered__");

// ── Configuration ──
const PORT = 4173;
const CONCURRENCY = Number(readArgument("--concurrency", "3"));
const TIMEOUT = Number(readArgument("--timeout", "15000"));
const HYDRATION_VIEWPORT = {
  width: Number(readArgument("--viewport-width", "1280")),
  height: Number(readArgument("--viewport-height", "900")),
  deviceScaleFactor: 1,
};
const STRICT = process.argv.includes("--strict");

const ARTICLES_DIR = path.resolve(ROOT, "..", "backend", "app", "data", "articles");

// ── Content selectors to wait for (route prefix → CSS selector) ──
const WAIT_FOR = [
  { prefix: "/relationship-patterns/", selector: '[data-prerender-ready="relationship-pattern-article"]' },
  { prefix: "/methodology", selector: '[data-prerender-ready="methodology"]' },
  { prefix: "/compare/", selector: ".comparison-table" },
  { prefix: "/faq", selector: ".content-page" },
  { prefix: "/compatibility", selector: ".compact-page" },
  { prefix: "/articles/", selector: ".article-content" },
  { prefix: "/compatibility/elements/", selector: ".landing-hero" },
  { prefix: "/elements/", selector: ".element-personality-hero" },
  { prefix: "/articles", selector: ".article-grid" },
  { prefix: "/", selector: ".bond-hero" },
];

